def write_areamap():
    os.makedirs(os.path.dirname(AREAMAP_PATH), exist_ok=True)
    if os.path.exists(AREAMAP_PATH):
        with open(AREAMAP_PATH, "r", encoding="utf-8") as f:
            existing = f.read()
        if existing.strip() == AREAMAP_CONTENT.strip():
            print("SKIP: areaMap.ts already up to date")
            return
    with open(AREAMAP_PATH, "w", encoding="utf-8") as f:
        f.write(AREAMAP_CONTENT)
    print("OK: src/data/areaMap.ts লেখা হয়েছে")

def patch_addpartform():
    if not os.path.exists(ADDPARTFORM_PATH):
        print("ERROR: AddPartForm.tsx পাওয়া যায়নি — path ঠিক আছে কিনা দেখো")
        sys.exit(1)
    with open(ADDPARTFORM_PATH, "r", encoding="utf-8") as f:
        content = f.read()

    if "detectDistrictFromArea" in content:
        print("SKIP: AddPartForm.tsx ইতিমধ্যে patched")
        return

    OLD_IMPORT = 'import { CITIES } from "../translations";'
    NEW_IMPORT = 'import { CITIES } from "../translations";\nimport { detectDistrictFromArea } from "../data/areaMap";'

    if OLD_IMPORT not in content:
        print("ERROR: import line খুঁজে পাওয়া যায়নি, ম্যানুয়ালি চেক করো")
        sys.exit(1)
